(self.webpackChunksite=self.webpackChunksite||[]).push([[4701],{6283:e=>{"use strict";e.exports=JSON.parse('{"slug":"crossy-road","title":"Crossy Road","authors":[{"name":"Lucas Alves","contact":"lucalvex","contactType":"github","contactUrl":"https://github.com/lucalvex"},{"name":"Matheus Campaner","contact":null,"contactType":null,"contactUrl":null}],"date":1753660800000,"readme":"<p>This is a simple clone of the classic game <strong>Crossy Road</strong>, made with the <strong>WASM-4</strong> engine using the <strong>Go</strong> language.</p>\\n<p>The objective of the game is to cross the street dodging cars and collecting coins to increase your score. The game restarts after each collision.</p>\\n<h2>Controls</h2>\\n<ul>\\n<li>\u2b06\ufe0f / \u2b07\ufe0f / \u2b05\ufe0f / \u27a1\ufe0f \u2014 move the character</li>\\n<li>\u24cd (X button) \u2014 start or restart the game</li>\\n</ul>\\n<h2>Credits</h2>\\n<p>Developed as part of the project for the Programming Language and Hardware and Software Interface Design courses - UEM, 2025/1.</p>"}')}}]);